from fastapi import Depends, Security

def test_depends_hashable():
    d1 = Depends(dependency=lambda x: x)
    d2 = Depends(dependency=lambda x: x)
    # Note: lambda x: x is not the same object, so d1 and d2 will have different hashes
    # unless we use the same dependency.

    # But they should be hashable.
    try:
        hash(d1)
        print("Depends is hashable")
    except TypeError as e:
        print(f"Depends is NOT hashable: {e}")

    # Test if they can be used in a set
    try:
        s = {d1, d1}
        print("Depends can be used in a set")
    except TypeError as e:
        print(f"Depends cannot be used in a set: {e}")

def test_security_hashable():
    s1 = Security(dependency=lambda x: x)
    try:
        hash(s1)
        print("Security is hashable")
    except TypeError as e:
        print(f"Security is NOT hashable: {e}")

    try:
        s = {s1, s1}
        print("Security can be used in a set")
    except TypeError as e:
        print(f"Security cannot be used in a set: {e}")

if __name__ == "__main__":
    test_depends_hashable()
    test_security_hashable()
